import java.util.*;

class Solution {
    public List<String> letterCombinations(String digits) {
        List<String> result = new ArrayList<>();
        if (digits == null || digits.isEmpty()) return result;   // 返回空列表

        String[] map = { "", "", "abc", "def", "ghi", "jkl",
                         "mno", "pqrs", "tuv", "wxyz" };

        result.add("");
        for (char c : digits.toCharArray()) {
            String letters = map[Character.getNumericValue(c)];
            List<String> next = new ArrayList<>();
            for (String p : result) {
                for (char ch : letters.toCharArray()) {
                    next.add(p + ch);
                }
            }
            result = next;
        }
        return result;
    }
}

import java.util.*;

class Solution {
    private static final String[] MAP = { "", "", "abc", "def", "ghi", "jkl",
                                         "mno", "pqrs", "tuv", "wxyz" };

    private List<String> result = new ArrayList<>();
    private StringBuilder sb = new StringBuilder();

    public List<String> letterCombinations(String digits) {
        if (digits == null || digits.isEmpty()) return new ArrayList<>();
        backtrack(digits, 0);
        return result;
    }

    private void backtrack(String digits, int index) {
        if (index == digits.length()) {
            result.add(sb.toString());
            return;
        }
        String letters = MAP[Character.getNumericValue(digits.charAt(index))];
        for (int i = 0; i < letters.length(); i++) {
            sb.append(letters.charAt(i));
            backtrack(digits, index + 1);
            sb.deleteCharAt(sb.length() - 1);   // 撤销
        }
    }
}

import java.util.*;

class Solution {
    private static final String[] MAP = { "", "", "abc", "def", "ghi", "jkl",
                                         "mno", "pqrs", "tuv", "wxyz" };

    public List<String> letterCombinations(String digits) {
        List<String> result = new ArrayList<>();
        if (digits == null || digits.isEmpty()) return result;

        char[] buf = new char[digits.length()];   // 定长，位置即深度
        backtrack(digits, 0, buf, result);
        return result;
    }

    private void backtrack(String digits, int index, char[] buf, List<String> result) {
        if (index == digits.length()) {
            result.add(new String(buf));      // 不是 buf.toString()
            return;
        }
        String letters = MAP[Character.getNumericValue(digits.charAt(index))];
        for (int i = 0; i < letters.length(); i++) {
            buf[index] = letters.charAt(i);   // 直接写，无需撤销
            backtrack(digits, index + 1, buf, result);
        }
    }
}
